// Updated CourseSearch.js functionality to fix the following:
// 1. Table should be filtered by selected campus, course, year.
// 2. Year chart should always show All Years, course-wise + campus-wise.

import React, { useState, useEffect, useRef } from 'react';
import Axios from 'axios';
import { Chart, registerables } from 'chart.js';
import './course.css';

Chart.register(...registerables);

function CourseSearch() {
  const [data, setData] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState('');
  const [selectedYear, setSelectedYear] = useState('');
  const [selectedCampus, setSelectedCampus] = useState('');
  const [courses, setCourses] = useState([]);
  const [years, setYears] = useState([]);
  const [campuses, setCampuses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const chartRef = useRef(null);
  const chartInstanceRef = useRef(null);
  const yearChartInstanceRef = useRef(null);

  useEffect(() => {
    fetchAllData();
    return () => {
      if (chartInstanceRef.current) chartInstanceRef.current.destroy();
      if (yearChartInstanceRef.current) yearChartInstanceRef.current.destroy();
    };
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const response = await Axios.get('http://localhost:3002/details');
      const users = response.data.users || [];
      setData(users);
      setCourses([...new Set(users.map((u) => u.course))].sort());
      setYears([...new Set(users.map((u) => u.year))].sort());
      setCampuses([...new Set(users.map((u) => u.campus))].sort());
      setLoading(false);
    } catch (error) {
      setLoading(false);
      console.error(error);
      setMessage('Error loading data');
    }
  };

  const filterData = () => {
    return data.filter((u) => {
      return (
        (!selectedCourse || u.course === selectedCourse) &&
        (!selectedYear || u.year === selectedYear) &&
        (!selectedCampus || u.campus === selectedCampus)
      );
    });
  };

  useEffect(() => {
    const filtered = filterData();
    if (selectedCourse) {
      updateMainChart(filtered);
      updateYearChart();
    }
  }, [selectedCourse, selectedYear, selectedCampus, data]);

  const updateMainChart = (filteredUsers) => {
    if (chartInstanceRef.current) chartInstanceRef.current.destroy();
    const ctx = chartRef.current?.getContext('2d');
    if (!ctx) return;

    const districtData = {};
    filteredUsers.forEach((u) => {
      const label = `${u.campus} - ${u.district}`;
      const count = Number.isFinite(u.Students) ? u.Students : 0;
      districtData[label] = (districtData[label] || 0) + count;
    });

    chartInstanceRef.current = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: Object.keys(districtData),
        datasets: [{
          label: 'Students',
          data: Object.values(districtData),
          backgroundColor: 'rgba(37, 99, 235, 0.6)'
        }]
      },
      options: {
        plugins: {
          title: {
            display: true,
            text: `Students in ${selectedCourse} ${selectedYear || ''}`
          },
          legend: { display: false }
        },
        scales: {
          y: { beginAtZero: true },
          x: { title: { display: true, text: 'Campus - District' } }
        }
      }
    });
  };

  const updateYearChart = () => {
    if (!selectedCourse) return;
    if (yearChartInstanceRef.current) yearChartInstanceRef.current.destroy();
    const ctx = document.getElementById('yearChart')?.getContext('2d');
    if (!ctx) return;

    const yearCounts = {};
    data.forEach((u) => {
      if (u.course === selectedCourse && (!selectedCampus || u.campus === selectedCampus)) {
        yearCounts[u.year] = (yearCounts[u.year] || 0) + (Number(u.Students) || 0);
      }
    });

    yearChartInstanceRef.current = new Chart(ctx, {
      type: 'line',
      data: {
        labels: Object.keys(yearCounts).sort(),
        datasets: [{
          label: 'Students (All Years)',
          data: Object.values(yearCounts),
          borderColor: 'rgba(75,192,192,1)',
          fill: false,
          tension: 0.2
        }]
      },
      options: {
        plugins: {
          title: {
            display: true,
            text: `All Year Summary for ${selectedCourse} ${selectedCampus && `(${selectedCampus})`}`
          }
        },
        scales: {
          y: { beginAtZero: true },
          x: { title: { display: true, text: 'Year' } }
        }
      }
    });
  };

  return (
    <div className="app-container">
      <div className="form-group">
        <label>Campus</label>
        <select value={selectedCampus} onChange={(e) => setSelectedCampus(e.target.value)}>
          <option value="">All</option>
          {campuses.map((c, i) => <option key={i} value={c}>{c}</option>)}
        </select>
      </div>
      <div className="form-group">
        <label>Course</label>
        <input list="course-options" value={selectedCourse} onChange={(e) => setSelectedCourse(e.target.value)} />
        <datalist id="course-options">
          {courses.map((c, i) => <option key={i} value={c} />)}
        </datalist>
      </div>
      <div className="form-group">
        <label>Year</label>
        <select value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
          <option value="">All</option>
          {years.map((y, i) => <option key={i} value={y}>{y}</option>)}
        </select>
      </div>

      <table className="data-table">
        <thead>
          <tr>
            <th>District</th>
            <th>Stream</th>
            <th>Course</th>
            <th>Campus</th>
            <th>Z-Range</th>
            <th>Students</th>
            <th>Year</th>
          </tr>
        </thead>
        <tbody>
          {filterData().map((row, idx) => (
            <tr key={idx}>
              <td>{row.district}</td>
              <td>{row.stream}</td>
              <td>{row.course}</td>
              <td>{row.campus}</td>
              <td>{row.zValue1} - {row.zValue2}</td>
              <td>{row.Students}</td>
              <td>{row.year}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {selectedCourse && filterData().length > 0 && (
        <>
          <div className="chart-container">
            <canvas ref={chartRef}></canvas>
          </div>
          <div className="chart-container">
            <canvas id="yearChart"></canvas>
          </div>
        </>
      )}
    </div>
  );
}

export default CourseSearch;
